export function getFinalizeSessionInstruction<
  TAccountPayer extends string,
  TAccountVault extends string,
  TAccountSession extends string,
  TAccountSessionRentRecipient extends string,
  TAccountPolicy extends string,
  TAccountTracker extends string,
  TAccountAgentSpendOverlay extends string,
  TAccountVaultTokenAccount extends string,
  TAccountOutputStablecoinAccount extends string,
  TAccountOutputSwapAccount extends string,
  TAccountProtocolTreasuryTokenAccount extends string,
  TAccountFeeDestinationTokenAccount extends string,
  TAccountTokenProgram extends string,
  TAccountSystemProgram extends string,
  TAccountInstructionsSysvar extends string,
  TAccountAuditLogSuccess extends string,
  TAccountAuditLogRejected extends string,
  TAccountSlotHashesSysvar extends string,
  TProgramAddress extends Address = typeof SIGIL_PROGRAM_ADDRESS,
>(
  input: FinalizeSessionInput<
    TAccountPayer,
    TAccountVault,
    TAccountSession,
    TAccountSessionRentRecipient,
    TAccountPolicy,
    TAccountTracker,
    TAccountAgentSpendOverlay,
    TAccountVaultTokenAccount,
    TAccountOutputStablecoinAccount,
    TAccountOutputSwapAccount,
    TAccountProtocolTreasuryTokenAccount,
    TAccountFeeDestinationTokenAccount,
    TAccountTokenProgram,
    TAccountSystemProgram,
    TAccountInstructionsSysvar,
    TAccountAuditLogSuccess,
    TAccountAuditLogRejected,
    TAccountSlotHashesSysvar
  >,
  config?: { programAddress?: TProgramAddress },
): FinalizeSessionInstruction<
  TProgramAddress,
  TAccountPayer,
  TAccountVault,
  TAccountSession,
  TAccountSessionRentRecipient,
  TAccountPolicy,
  TAccountTracker,
  TAccountAgentSpendOverlay,
  TAccountVaultTokenAccount,
  TAccountOutputStablecoinAccount,
  TAccountOutputSwapAccount,
  TAccountProtocolTreasuryTokenAccount,
  TAccountFeeDestinationTokenAccount,
  TAccountTokenProgram,
  TAccountSystemProgram,
  TAccountInstructionsSysvar,
  TAccountAuditLogSuccess,
  TAccountAuditLogRejected,
  TAccountSlotHashesSysvar
> {
  // Program address.
  const programAddress = config?.programAddress ?? SIGIL_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    payer: { value: input.payer ?? null, isWritable: true },
    vault: { value: input.vault ?? null, isWritable: true },
    session: { value: input.session ?? null, isWritable: true },
    sessionRentRecipient: {
      value: input.sessionRentRecipient ?? null,
      isWritable: true,
    },
    policy: { value: input.policy ?? null, isWritable: false },
    tracker: { value: input.tracker ?? null, isWritable: true },
    agentSpendOverlay: {
      value: input.agentSpendOverlay ?? null,
      isWritable: true,
    },
    vaultTokenAccount: {
      value: input.vaultTokenAccount ?? null,
      isWritable: true,
    },
    outputStablecoinAccount: {
      value: input.outputStablecoinAccount ?? null,
      isWritable: true,
    },
    outputSwapAccount: {
      value: input.outputSwapAccount ?? null,
      isWritable: true,
    },
    protocolTreasuryTokenAccount: {
      value: input.protocolTreasuryTokenAccount ?? null,
      isWritable: true,
    },
    feeDestinationTokenAccount: {
      value: input.feeDestinationTokenAccount ?? null,
      isWritable: true,
    },
    tokenProgram: { value: input.tokenProgram ?? null, isWritable: false },
    systemProgram: { value: input.systemProgram ?? null, isWritable: false },
    instructionsSysvar: {
      value: input.instructionsSysvar ?? null,
      isWritable: false,
    },
    auditLogSuccess: { value: input.auditLogSuccess ?? null, isWritable: true },
    auditLogRejected: {
      value: input.auditLogRejected ?? null,
      isWritable: true,
    },
    slotHashesSysvar: {
      value: input.slotHashesSysvar ?? null,
      isWritable: false,
    },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedInstructionAccount
  >;

  // Resolve default values.
  if (!accounts.tokenProgram.value) {
    accounts.tokenProgram.value =
      "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA" as Address<"TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA">;
  }
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value =
      "11111111111111111111111111111111" as Address<"11111111111111111111111111111111">;
  }
  if (!accounts.instructionsSysvar.value) {
    accounts.instructionsSysvar.value =
      "Sysvar1nstructions1111111111111111111111111" as Address<"Sysvar1nstructions1111111111111111111111111">;
  }
  if (!accounts.slotHashesSysvar.value) {
    accounts.slotHashesSysvar.value =
      "SysvarS1otHashes111111111111111111111111111" as Address<"SysvarS1otHashes111111111111111111111111111">;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta("payer", accounts.payer),
      getAccountMeta("vault", accounts.vault),
      getAccountMeta("session", accounts.session),
      getAccountMeta("sessionRentRecipient", accounts.sessionRentRecipient),
      getAccountMeta("policy", accounts.policy),
      getAccountMeta("tracker", accounts.tracker),
      getAccountMeta("agentSpendOverlay", accounts.agentSpendOverlay),
      getAccountMeta("vaultTokenAccount", accounts.vaultTokenAccount),
      getAccountMeta(
        "outputStablecoinAccount",
        accounts.outputStablecoinAccount,
      ),
      getAccountMeta("outputSwapAccount", accounts.outputSwapAccount),
      getAccountMeta(
        "protocolTreasuryTokenAccount",
        accounts.protocolTreasuryTokenAccount,
      ),
      getAccountMeta(
        "feeDestinationTokenAccount",
        accounts.feeDestinationTokenAccount,
      ),
      getAccountMeta("tokenProgram", accounts.tokenProgram),
      getAccountMeta("systemProgram", accounts.systemProgram),
      getAccountMeta("instructionsSysvar", accounts.instructionsSysvar),
      getAccountMeta("auditLogSuccess", accounts.auditLogSuccess),
      getAccountMeta("auditLogRejected", accounts.auditLogRejected),
      getAccountMeta("slotHashesSysvar", accounts.slotHashesSysvar),
    ],
    data: getFinalizeSessionInstructionDataEncoder().encode({}),
    programAddress,
  } as FinalizeSessionInstruction<
    TProgramAddress,
    TAccountPayer,
    TAccountVault,
    TAccountSession,
    TAccountSessionRentRecipient,
    TAccountPolicy,
    TAccountTracker,
    TAccountAgentSpendOverlay,
    TAccountVaultTokenAccount,
    TAccountOutputStablecoinAccount,
    TAccountOutputSwapAccount,
    TAccountProtocolTreasuryTokenAccount,
    TAccountFeeDestinationTokenAccount,
    TAccountTokenProgram,
    TAccountSystemProgram,
    TAccountInstructionsSysvar,
    TAccountAuditLogSuccess,
    TAccountAuditLogRejected,
    TAccountSlotHashesSysvar
  >);
}

export type ParsedFinalizeSessionInstruction<
  TProgram extends string = typeof SIGIL_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    /**
     * C-1 fix: Boxed to keep `FinalizeSession::try_accounts` under the 4096-byte
     * BPF stack frame after the C-1 relocation added the protocol-treasury +
     * fee-destination token accounts to this struct. Box moves the deserialized
     * account to the heap; handler access is unchanged (transparent auto-deref).
     */
    vault: TAccountMetas[1];
    /**
     * Session rent is returned to the session's agent (who paid for it).
     * Seeds include token_mint for per-token concurrent sessions.
     * C-1 fix: Boxed (see `vault`) to reclaim BPF stack-frame headroom for the
     * relocated fee token accounts. `close` is unaffected by Box.
     */
    session: TAccountMetas[2];
    sessionRentRecipient: TAccountMetas[3];
    /**
     * Policy config for outcome-based cap checking during finalization.
     * Boxed to keep `try_accounts` under the 4096-byte BPF stack limit: PolicyConfig
     * is ~1.3KB and the M1 output-ownership account pushed the FinalizeSession context
     * 8 bytes over on stable Anchor (runtime "Access violation in stack frame").
     * Boxing moves the deserialized account to the heap (transparent auto-deref in the
     * handler) — no behavior change.
     */
    policy: TAccountMetas[4];
    /** Zero-copy SpendTracker for recording non-stablecoin swap value */
    tracker: TAccountMetas[5];
    /** Zero-copy AgentSpendOverlay — per-agent rolling spend */
    agentSpendOverlay: TAccountMetas[6];
    /**
     * Vault's PDA token account for the session's token.
     * L2-1 (audit 2026-06-15): fail-fast that, when present, this ATA is owned
     * by the vault PDA. The outcome path already re-reads the raw post-CPI
     * owner field and asserts owner==vault, so this is defense-in-depth — but
     * it rejects a substituted token account at account-resolution rather than
     * deep in the handler.
     * C-1 fix: Boxed (see `vault`) to reclaim BPF stack-frame headroom.
     */
    vaultTokenAccount?: TAccountMetas[7] | undefined;
    /**
     * Vault's stablecoin ATA for outcome-based spending verification.
     * Required when session.output_mint != Pubkey::default() (all spending).
     * C-1 fix: Boxed (see `vault`) to reclaim BPF stack-frame headroom.
     */
    outputStablecoinAccount?: TAccountMetas[8] | undefined;
    /**
     * M1 output-ownership closure — the validate-pinned VAULT-OWNED account an
     * acquiring (stablecoin-input) swap must have credited. finalize re-reads its
     * raw post-CPI bytes and asserts owner==vault, mint==pinned, and balance
     * strictly INCREASED. Owner is checked in the handler (like F-Q8 above), not
     * as a struct constraint. Boxed to keep try_accounts under the 4096 BPF
     * stack limit. Required whenever a stablecoin-input spend moves value.
     */
    outputSwapAccount?: TAccountMetas[9] | undefined;
    /**
     * C-1 fix: protocol treasury token account. RELOCATED here from
     * validate_and_authorize — the protocol fee is now collected at finalize on
     * the MEASURED spend (inside the caps), not upfront on the declared amount.
     * Required (Some) only on a stablecoin-input spend with actual_spend > 0;
     * None for non-spending / non-stablecoin-input / expired sessions. Boxed to
     * keep `try_accounts` under the 4096-byte BPF stack frame.
     */
    protocolTreasuryTokenAccount?: TAccountMetas[10] | undefined;
    /**
     * C-1 fix: developer fee destination token account (see above). Required
     * only when the vault's developer_fee_rate > 0 on a stablecoin-input spend
     * with actual_spend > 0. Boxed for the same stack-frame reason.
     */
    feeDestinationTokenAccount?: TAccountMetas[11] | undefined;
    tokenProgram: TAccountMetas[12];
    systemProgram: TAccountMetas[13];
    /** Instructions sysvar for post-finalize instruction verification. */
    instructionsSysvar: TAccountMetas[14];
    /**
     * Phase 7 — SUCCESS-path audit log. Written when the finalize completes
     * the non-expired branch.
     */
    auditLogSuccess: TAccountMetas[15];
    /**
     * Phase 7 — REJECTED-path audit log. Written when the finalize takes
     * the expired branch (permissionless-crank cleanup). Audit #2 F-19
     * keeps this separate from the success buffer so a crank-attacker
     * cannot displace legitimate success history.
     */
    auditLogRejected: TAccountMetas[16];
    slotHashesSysvar: TAccountMetas[17];
  };
  data: FinalizeSessionInstructionData;
};

export function parseFinalizeSessionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedFinalizeSessionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 18) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 18,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === SIGIL_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      vault: getNextAccount(),
      session: getNextAccount(),
      sessionRentRecipient: getNextAccount(),
      policy: getNextAccount(),
      tracker: getNextAccount(),
      agentSpendOverlay: getNextAccount(),
      vaultTokenAccount: getNextOptionalAccount(),
      outputStablecoinAccount: getNextOptionalAccount(),
      outputSwapAccount: getNextOptionalAccount(),
      protocolTreasuryTokenAccount: getNextOptionalAccount(),
      feeDestinationTokenAccount: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      instructionsSysvar: getNextAccount(),
      auditLogSuccess: getNextAccount(),
      auditLogRejected: getNextAccount(),
      slotHashesSysvar: getNextAccount(),
    },
    data: getFinalizeSessionInstructionDataDecoder().decode(instruction.data),
  };
}
